<script lang="ts">
  import {command} from './api';import {createRequestGate} from './requestGate.js';import {onDestroy} from 'svelte';
  import KeyboardLayout from './KeyboardLayout.svelte';
  import {lightingChanges} from './lightingDraft.js';
  interface Mode {id:number;label:string;brightnessEditable:boolean;speedEditable:boolean;colorEditable:boolean}
  interface Snapshot {deviceId:string;model:string;sampledAt:number;stateToken:string;mode:number;brightness:number|null;speed:number|null;multiColor:boolean|null;rgb:[number,number,number]|null;colorError?:string|null;modes:Mode[];unsupported:string[]}
  let rgb=$state<[number,number,number]|null>(null);let hex=$state('#ffffff');
  let {deviceId}:{deviceId:string|null}=$props();let snapshot=$state<Snapshot|null>(null);let mode=$state(0);let brightness=$state<number|null>(null);let speed=$state<number|null>(null);let multiColor=$state<boolean|null>(null);let busy=$state(false);let confirmed=$state(false);let error=$state('');let success=$state('');let loadedId='';const requests=createRequestGate();
  const selected=$derived(snapshot?.modes.find(m=>m.id===mode));
  const modeChanged=$derived(!!snapshot&&mode!==snapshot.mode);
  const parametersReady=$derived(!!snapshot&&confirmed&&!modeChanged);
  const changes=$derived(lightingChanges(snapshot,{mode,brightness,speed,multiColor,rgb},selected));
  const dirty=$derived(Object.keys(changes).length>0);const invalid=$derived(!modeChanged&&((selected?.colorEditable&&multiColor===false&&rgb&&(!/^#[0-9a-f]{6}$/i.test(hex)||rgb.some(value=>!Number.isInteger(value)||value<0||value>255)))||(selected?.brightnessEditable&&brightness!==null&&(!Number.isInteger(brightness)||brightness<1||brightness>4))||(selected?.speedEditable&&speed!==null&&(!Number.isInteger(speed)||speed<1||speed>4))));
  const message=(e:unknown)=>e&&typeof e==='object'&&'message'in e?String(e.message):String(e);
  function accept(value:Snapshot){snapshot=value;mode=value.mode;brightness=value.brightness;speed=value.speed;multiColor=value.multiColor;rgb=value.rgb?[...value.rgb]:null;hex=rgb?'#'+rgb.map(v=>v.toString(16).padStart(2,'0')).join(''):'#ffffff';confirmed=true;}
  function colorInput(value:string){hex=value;if(/^#[0-9a-f]{6}$/i.test(value))rgb=[parseInt(value.slice(1,3),16),parseInt(value.slice(3,5),16),parseInt(value.slice(5,7),16)];}
  function channelInput(index:number,value:number){if(!rgb)return;const next:[number,number,number]=[...rgb];next[index]=value;rgb=next;if(next.every(channel=>Number.isInteger(channel)&&channel>=0&&channel<=255))hex='#'+next.map(channel=>channel.toString(16).padStart(2,'0')).join('');}
  async function read(){if(!deviceId||busy)return;const current=requests.begin();busy=true;error='';success='';try{const value=await command<Snapshot>('read_keyboard_lighting',{deviceId});if(current())accept(value);}catch(e){if(current()){error=message(e);confirmed=false;}}finally{if(current())busy=false;}}
  async function apply(){if(!deviceId||!snapshot||busy||!dirty||invalid||!selected||!confirmed)return;const current=requests.begin();busy=true;error='';success='';try{const value=await command<Snapshot>('apply_keyboard_lighting',{deviceId,change:{expectedState:snapshot.stateToken,...changes}});if(current()){accept(value);success='灯效已写入并完整读回确认。';}}catch(e){if(current()){error=`${message(e)}。请重新读取核对设备状态。`;confirmed=false;}}finally{if(current())busy=false;}}
  export function hasUnsavedChanges(){return dirty||busy;}export function isOperationPending(){return busy;}
  $effect(()=>{if(loadedId!==(deviceId||'')){loadedId=deviceId||'';requests.invalidate();snapshot=null;busy=false;confirmed=false;if(deviceId)void read();}});onDestroy(()=>requests.invalidate());
</script>
<div class="lighting-heading"><h3>灯光设置</h3><span>布局示意 · 仅显示已读取的单色参数</span></div><KeyboardLayout brightness={parametersReady?brightness:null} color={parametersReady&&multiColor===false&&rgb?hex:null}/>
{#if snapshot}<div class="lighting-current"><span>最近读取的模式</span><strong>{snapshot.modes.find(item=>item.id===snapshot?.mode)?.label??'未知模式'}</strong></div><div class="lighting-editor"><div class="lighting-modes"><h4>选择灯效</h4><div class="mode-grid">{#each snapshot.modes as item}<button class:active={mode===item.id} aria-pressed={mode===item.id} disabled={busy||!confirmed} onclick={()=>mode=item.id}>{item.label}{#if mode===item.id}<span aria-hidden="true">✓</span>{/if}</button>{/each}</div><div class="lighting-custom"><h4>逐键灯光</h4><span>逐键 DIY 与自定义灯光尚未开放。</span></div></div><div class="lighting-controls"><h4>模式参数</h4>
{#if modeChanged}<div class="mode-pending" role="status"><strong>先应用模式，再调整参数</strong><p>目标模式的亮度、速度和颜色尚未读取。此次只切换模式，保留目标槽中的参数。</p></div>
{:else}<label for="lighting-speed">速度 <output>{selected?.speedEditable?speed??'未知':'此模式不适用'}</output></label><input id="lighting-speed" type="range" min="1" max="4" value={speed??1} oninput={e=>speed=Number(e.currentTarget.value)} disabled={busy||!parametersReady||speed===null||!selected?.speedEditable}/><label for="lighting-brightness">亮度 <output>{selected?.brightnessEditable?brightness??'未知':'此模式不适用'}</output></label><input id="lighting-brightness" type="range" min="1" max="4" value={brightness??1} oninput={e=>brightness=Number(e.currentTarget.value)} disabled={busy||!parametersReady||brightness===null||!selected?.brightnessEditable}/>
{#if selected?.colorEditable}<label for="lighting-multicolor">颜色模式</label><select id="lighting-multicolor" bind:value={multiColor} disabled={busy||!parametersReady||multiColor===null}><option value={null} disabled>未知</option><option value={true}>多色</option><option value={false}>单色</option></select><div class="color-editor">{#if rgb}<label for="lighting-color">单色颜色</label><input id="lighting-color" type="color" value={hex} oninput={e=>colorInput(e.currentTarget.value)} disabled={busy||!parametersReady||multiColor!==false}/><label for="lighting-hex">Hex</label><input id="lighting-hex" type="text" value={hex} maxlength="7" oninput={e=>colorInput(e.currentTarget.value)} disabled={busy||!parametersReady||multiColor!==false}/><div class="rgb-channels">{#each ['R','G','B'] as channel,index}<label for={`lighting-channel-${index}`}>{channel}<input id={`lighting-channel-${index}`} type="number" min="0" max="255" value={rgb[index]} oninput={e=>channelInput(index,Number(e.currentTarget.value))} disabled={busy||!parametersReady||multiColor!==false||!!snapshot.colorError}/></label>{/each}</div>{:else}<p class="settings-intro">单色颜色尚未读取。</p>{/if}{#if snapshot.colorError}<p class="message error">{snapshot.colorError}</p>{/if}</div>{/if}{/if}</div></div>
{#if dirty}<div class="change-preview"><strong>待应用的灯效</strong>{#each Object.entries(changes) as [key,value]}<p>{({mode:'模式',brightness:'亮度',speed:'速度',multiColor:'多色'} as Record<string,string>)[key]} → {key==='mode'?selected?.label:String(value)}</p>{/each}</div>{/if}
{#each snapshot.unsupported as reason}<p class="settings-intro">{reason}</p>{/each}{:else}<div class="settings-empty" role="status"><strong>{busy?'正在读取灯光设置…':!deviceId?'连接键盘后读取灯效':'尚未取得灯光设置'}</strong><p>读取前不显示设备灯色、亮度或速度。</p></div>{/if}
{#if error}<p class="message error" role="alert">{error}</p>{/if}{#if success}<p class="settings-success" role="status">{success}</p>{/if}
<div class="settings-actions"><span role="status">{busy?'等待设备确认…':!confirmed&&dirty?'请先撤回预览再重新读取核对。':modeChanged?'仅切换模式，目标参数保持原值。':dirty?'灯效预览尚未应用':''}</span><button class="secondary" disabled={!deviceId||busy||dirty} onclick={read}>重新读取</button><button class="secondary" disabled={!dirty||busy} onclick={()=>{if(snapshot){const wasConfirmed=confirmed;accept(snapshot);confirmed=wasConfirmed;}}}>撤回预览</button><button class="primary" disabled={!dirty||busy||invalid||!selected||!confirmed} onclick={apply}>{busy?'等待设备确认…':modeChanged?'应用模式并读回':'应用到设备'}</button></div>
<style>
 .lighting-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:16px}.lighting-heading h3{font-size:16px;font-weight:600;margin:0}.lighting-heading span,.lighting-custom span{font-size:12px;color:var(--muted);line-height:1.65}.lighting-current{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:0 0 24px;font-size:12px}.lighting-current span{color:var(--muted)}.lighting-current strong{font-size:14px;font-weight:600}.lighting-editor{display:grid;grid-template-columns:minmax(0,2fr) minmax(208px,1fr);gap:24px}.lighting-modes,.lighting-controls{min-width:0}.lighting-modes h4,.lighting-controls h4,.lighting-custom h4{font-size:14px;font-weight:600;margin:0 0 16px}.mode-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.mode-grid button{display:flex;justify-content:space-between;align-items:center;gap:8px;min-width:0;min-height:40px;padding:8px 12px;border:1px solid var(--quiet-line);border-radius:8px;background:var(--control);color:var(--ink);font:inherit;font-size:12px;text-align:left;overflow-wrap:anywhere}.mode-grid button.active{color:var(--accent);background:var(--glass-chrome,var(--control));border-color:var(--accent)}.mode-grid button>span{font-size:14px;flex:none}.lighting-controls{border-left:1px solid var(--quiet-line);padding-left:24px}.lighting-controls label{display:flex;justify-content:space-between;gap:8px;margin:24px 0 12px;font-size:12px}.lighting-controls output{color:var(--muted);text-align:right}.lighting-controls input{width:100%;min-width:0;accent-color:var(--accent)}.lighting-controls select{width:100%;padding:8px 12px;background:var(--control);border:1px solid var(--line);border-radius:8px;color:var(--ink);font:inherit;font-size:12px;min-height:36px}.lighting-custom{padding-top:24px;margin-top:24px;border-top:1px solid var(--quiet-line)}.lighting-custom h4{margin-bottom:8px}.color-editor input[type=text]{width:100%;background:var(--control);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 12px;font:inherit;font-size:12px}.color-editor input[type=color]{height:40px;padding:0;border:0;background:transparent}.rgb-channels{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.lighting-controls .rgb-channels label{display:flex;flex-direction:column;gap:8px;margin:16px 0 0}.rgb-channels input{background:var(--control);border:1px solid var(--line);border-radius:8px;padding:8px;color:var(--ink);font:inherit;font-size:12px}.mode-pending{padding:16px;background:var(--warning-soft);color:var(--warning);border-radius:12px;font-size:12px;line-height:1.65}.mode-pending strong{font-weight:600}.mode-pending p{margin:8px 0 0}@media(max-width:760px){.lighting-editor{grid-template-columns:1fr}.lighting-controls{border-left:0;border-top:1px solid var(--quiet-line);padding:24px 0 0}.lighting-heading{align-items:flex-start;flex-direction:column;gap:8px}}@media(max-width:450px){.mode-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
